/bin/bash -lc "node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { setTimeout } from 'node:timers/promises';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '18080', DB_PATH: join(directory, 'launch.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'], detached: true });
let logs = '';
child.stdout.on('data', chunk => { logs += chunk; });
child.stderr.on('data', chunk => { logs += chunk; });
try {
  let healthy = false;
  for (let attempt = 0; attempt < 100; attempt++) {
    if (child.exitCode "'!== null) throw new Error(logs);
    try {
      const response = await fetch('"'http://127.0.0.1:18080/health');
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { status: 'ok' });
      healthy = true;
      break;
    } catch { await setTimeout(20); }
  }
  assert.ok(healthy, logs);
  const page = await fetch('http://127.0.0.1:18080/');
  assert.equal(page.status, 200);
  console.log('npm start: health and root page passed with configured PORT and DB_PATH');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
EOF"
